INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente de 55 anos mostra cine-aprisonamento de um cateter na artéria coronária direita, seguido de uma imagem de dupla luz e progressão retrógrada de contraste na parede da aorta. Qual a complicação ocorrida?", "options": {"a": "Infarto Benigno.", "b": "Dissecção coronariana iatrogênica com extensão para a aorta ascendente.", "c": "Alergia ao contraste.", "d": "Perfuração pulmonar.", "e": "Cura da asma."}, "answer": "b", "rationale": "A manipulação de cateteres pode causar dissecção da íntima.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Emergência em hemodinâmica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Hemodinâmica", "Complicação", "SCA"]}', 176, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "No contexto da SCA, qual a principal utilidade do uso de Morfina (ou outros opioides) além do controle da dor?", "options": {"a": "Desobstruir a artéria.", "b": "Reduzir a ansiedade e promover venodilatação (redução da pré-carga), sendo particularmente útil no edema agudo de pulmão associado.", "c": "Curar a gripe.", "d": "Impedir o sangramento.", "e": "Substituir o betabloqueador."}, "answer": "b", "rationale": "A morfina tem efeitos hemodinâmicos benéficos, mas deve ser usada com cautela pois pode retardar a absorção de antiagregantes orais.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Papel terapêutico sintomático e hemodinâmico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Farmacologia", "Morfina", "SCA"]}', 177, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A presença de sopro sistólico rude, em borda esternal esquerda baixa, que surge no 4º dia pós-infarto anterior, associado a choque cardiogênico súbito, sugere:", "options": {"a": "Estenose Aórtica.", "b": "Comunicação Interventricular (CIV) pós-infarto por ruptura do septo interventricular.", "c": "Normalidade.", "d": "Pneumonia de base.", "e": "Derrame pericárdico."}, "answer": "b", "rationale": "A ruptura do septo cria um shunt esquerda-fora-direita agudo.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Emergência cirúrgica mecânica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "CIV", "IAM", "Complicação"]}', 178, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal recomendação das diretrizes para o manejo da dor torácica no Pronto Socorro em relação ao tempo de realização do primeiro ECG?", "options": {"a": "Realizar em até 60 minutos.", "b": "Realizar e interpretar em até 10 minutos da chegada (door-to-ECG time).", "c": "Apenas após o resultado da troponina.", "d": "Quando o médico tiver tempo.", "e": "Apenas se a dor for muito forte."}, "answer": "b", "rationale": "O diagnóstico de IAM com supra deve ser imediato para iniciar a reperfusão.", "option_rationales": {"a": "Incorreta. Tempo excessivo.", "b": "Correta. Meta de qualidade assistencial.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "ECG", "SCA", "Tempo-Dependente"]}', 179, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre o fenômeno de ''roubo de fluxo'' coronariano induzido pelo dipiridamol, qual o seu efeito na reserva de fluxo coronário?", "options": {"a": "Aumenta a reserva.", "b": "Exacerba a diferença de perfusão entre áreas irrigadas por vasos normais (que dilatam) e vasos estenóticos (que não dilatam ou sofrem queda de pressão distal).", "c": "Não altera nada.", "d": "Cura o infarto.", "e": "Diminui o colesterol."}, "answer": "b", "rationale": "É a base fisiopatológica dos testes de estresse farmacológico vasodilatador.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Mecanismo de diagnóstico por imagem.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Diagnóstico", "Vasodilatador", "SCA"]}', 180, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia shows uma artéria circunflexa dominante. O que isso significa anatomicamente?", "options": {"a": "A circunflexa é a artéria mais importante do corpo.", "b": "A artéria descendente posterior e o nó AV são originados da artéria circunflexa, em vez da coronária direita.", "c": "O paciente tem dois corações.", "d": "A coronária direita não existe.", "e": "O paciente é canhoto."}, "answer": "b", "rationale": "Dominância é definida pela artéria que dá origem à descendente posterior (85% CD, 10% CX, 5% codominância).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Variante de anatomia coronariana.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Anatomia", "Dominância", "Vascular"]}', 181, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal causa de elevação de troponina em pacientes com Sepse grave ou Choque Séptico, na AUSÊNCIA de lesão coronariana obstrutiva, é:", "options": {"a": "Infarto tipo 1.", "b": "Infarto tipo 2 (desbalanceamento entre oferta e demanda de oxigênio devido à taquicardia, hipotensão e hipóxia sistêmica).", "c": "O laboratório está errado.", "d": "Efeito do antibiótico.", "e": "Falta de açúcar."}, "answer": "b", "rationale": "A troponina reflete injúria miocárdica, que pode ter causas não coronarianas.", "option_rationales": {"a": "Incorreta. Exige ruptura de placa.", "b": "Correta. Diagnóstico diferencial frequente na UTI.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Troponina", "Sepse", "Diagnóstico"]}', 182, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal indicação para o uso de desfibrilação elétrica imediata (choque) em um paciente com SCA?", "options": {"a": "Controlar a pressão arterial.", "b": "Tratar Fibrilação Ventricular (FV) ou Taquicardia Ventricular (TV) sem pulso.", "c": "Abaixar a febre.", "d": "Curar a asma.", "e": "Substituir o marcapasso."}, "answer": "b", "rationale": "O tratamento para FV/TV sem pulso é o choque elétrico precoce.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Manobra de ressuscitação vital.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Desfibrilação", "Arritmias", "SCA"]}', 183, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre o uso de Heparina de Baixo Peso Molecular (Enoxaparina) na SCA, em pacientes com insuficiência renal (clearance de creatinina < 30 ml/min), qual a recomendação?", "options": {"a": "Manter a dose normal.", "b": "Reduzir a dose (ex: 1 mg/kg 1x ao dia) ou dar preferência à Heparina Não Fracionada (HNF).", "c": "Suspender e não dar nada.", "d": "Dar dose tripla.", "e": "Dar antibiótico junto."}, "answer": "b", "rationale": "A enoxaparina é eliminada pelos rins e pode acumular em renais crônicos, aumentando o risco de sangramento.", "option_rationales": {"a": "Incorreta. Risco de sangramento excessivo.", "b": "Correta. Ajuste de dose por segurança.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Farmacologia", "Rim", "Segurança"]}', 184, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente mostra uma artéria descendente anterior que termina antes do ápice cardíaco (DA curta). Qual artéria costuma compensar a irrigação do ápice nestes casos?", "options": {"a": "Não há compensação.", "b": "Uma artéria descendente posterior (CD) ou um ramo marginal (CX) mais longo que contorna o ápice.", "c": "O pulmão.", "d": "A aorta.", "e": "O fígado."}, "answer": "b", "rationale": "A circulação coronariana busca manter a perfusão de todas as áreas do miocárdio.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Nuance de anatomia compensatória.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Anatomia", "SCA", "Vascular"]}', 185, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual o principal critério para definir se um paciente com IAMssST deve ir para o cateterismo de URGÊNCIA (vias muito rápidas - < 2h)?", "options": {"a": "Escore TIMI baixo.", "b": "Instabilidade hemodinâmica (choque), dor refratária ao tratamento, arritmias ventriculares fatais ou insuficiência cardíaca aguda.", "c": "Paciente jovem.", "d": "Paciente que mora perto do hospital.", "e": "Paciente tabagista."}, "answer": "b", "rationale": "Esses critérios indicam extrema gravidade e risco iminente de morte se a artéria não for aberta.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Estratificação de risco dinâmica (vias imediatas).", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Diretrizes", "SCA", "Conduta"]}', 186, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal indicação para o uso de Oxigênio suplementar na fase aguda da SCA é:", "options": {"a": "Em todos os pacientes para melhorar o conforto.", "b": "Apenas em pacientes hipoxêmicos (Saturação de O2 < 90% ou PaO2 < 60 mmHg) ou com desconforto respiratório franco.", "c": "Para desentupir as artérias.", "d": "Para acalmar o paciente.", "e": "Sempre com máscara de alta concentração."}, "answer": "b", "rationale": "O oxigênio liberal (em quem não precisa) pode causar vasoconstrição coronariana e aumentar o tamanho do infarto.", "option_rationales": {"a": "Incorreta. Pode ser deletério.", "b": "Correta. Uso baseado em evidência atual (estudo DETO2X-AMI).", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Oxigênio", "SCA", "Segurança"]}', 187, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A presença de ''clique'' sistólico seguido de sopro telessistólico no foco mitral, que surge após um infarto agudo, sugere:", "options": {"a": "Estenose Mitral.", "b": "Prolapso de Valva Mitral agudo devido a disfunção de músculo papilar.", "c": "Normalidade.", "d": "Infecção pulmonar.", "e": "Cura da arritmia."}, "answer": "b", "rationale": "A isquemia do papilar altera a competência da válvula.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Semiologia cardiovascular aplicada.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Mitral", "IAM", "Semiologia"]}', 188, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal causa de mortalidade em pacientes multiarteriais diabéticos submetidos a CRVM vs ICP a longo prazo?", "options": {"a": "AVC.", "b": "Infarto agudo do miocárdio recorrente (maior na ICP) e necessidade de nova revascularização.", "c": "Câncer.", "d": "Infecção renal.", "e": "Acidentes."}, "answer": "b", "rationale": "O stent trata o ponto da lesão, a cirurgia (ponte) protege o vaso distalmente contra futuras lesões proximais.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Racional da superioridade da cirurgia em multiarteriais.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "CRVM", "SCA", "Diabetes"]}', 189, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente mostra uma ponte miocárdica (myocardial bridge) sobre a artéria descendente anterior. No que consiste esse achado?", "options": {"a": "O paciente tem um stent natural.", "b": "Um segmento da artéria coronária (que deveria ser epicárdica) mergulha para dentro do miocárdio, sendo comprimido durante a sístole.", "c": "O paciente tem um tumor.", "d": "A artéria está entupida por gordura.", "e": "É um defeito do nascimento dos pulmões."}, "answer": "b", "rationale": "Embora geralmente benigna, pode causar isquemia se for longa ou profunda.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Variante anatômica frequente.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Anatomia", "Ponte Miocárdica", "SCA"]}', 190, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual o principal benefício do uso de betabloqueadores orais nas primeiras 24 horas de um infarto agudo do miocárdio?", "options": {"a": "Aumentar a força de contração.", "b": "Reduzir o consumo de oxigênio pelo miocárdio (reduzindo FC e contratilidade) e prevenir arritmias ventriculares fatais.", "c": "Baixar o açúcar.", "d": "Limpar as artérias.", "e": "Combater infecções."}, "answer": "b", "rationale": "O betabloqueio diminui o estresse cardíaco na fase aguda da necrose.", "option_rationales": {"a": "Incorreta. Betabloqueador é inotrópico negativo.", "b": "Correta. Papel protetor clássico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Farmacologia", "Betabloqueador", "SCA"]}', 191, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre o manejo da SCA em pacientes com Doença Renal Crônica avançada, qual a principal preocupação no uso de inibidores da GP IIb/IIIa (ex: Tirofiban)?", "options": {"a": "Eles não funcionam.", "b": "Risco altíssimo de sangramento (a dose deve ser ajustada ou a droga evitada pelo acúmulo e pela disfunção plaquetária já existente na uremia).", "c": "Causa febre.", "d": "Muda a cor da urina.", "e": "Não há risco nenhum."}, "answer": "b", "rationale": "O Tirofiban é de eliminação renal.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Segurança farmacológica na nefrologia.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Segurança", "Rim", "Tirofiban"]}', 192, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia shows uma ''fístula coronariana''. No que consiste essa anomalia?", "options": {"a": "Uma artéria entupida.", "b": "Uma comunicação anômala entre uma artéria coronária e uma câmara cardíaca (ex: VD, AD) ou um grande vaso (ex: v. cava, a. pulmonar).", "c": "Um tumor no coração.", "d": "Um stent quebrado.", "e": "Uma infecção no cateter."}, "answer": "b", "rationale": "Fístulas podem causar ''roubo de fluxo'' e isquemia.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Definição de anomalia vascular cardíaca.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Fístula", "Anatomia", "SCA"]}', 193, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal recomendação para o uso de Enoxaparina em um paciente com IAM com supra de ST que será submetido a ICP primária (já recebeu 0,5 mg/kg EV no pronto socorro)?", "options": {"a": "Dar mais 1 mg/kg SC.", "b": "Geralmente não é necessário dose adicional durante o procedimento se o tempo da última dose for < 8 horas; se for necessário, usa-se bólus adicional EV.", "c": "Suspender e dar apenas soro.", "d": "Dar dose dobrada.", "e": "Não usar heparina na ICP."}, "answer": "b", "rationale": "O objetivo é manter a anticoagulação estável durante o procedimento.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Protocolo de anticoagulação em intervenção.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Hemodinâmica", "Enoxaparina", "SCA"]}', 194, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal causa de reinfarto ou trombose de stent no primeiro mês após uma SCA é:", "options": {"a": "Uso de café.", "b": "Má adesão à terapia antiagregante dupla (DAPT) ou subexpansão técnica do stent durante o implante.", "c": "Excesso de exercício.", "d": "Falta de vitaminas.", "e": "Pneumonia."}, "answer": "b", "rationale": "A DAPT é a garantia de que o stent não vai trombosar enquanto não for endotelizado.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Causas evitáveis de eventos graves.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "SCA", "Stent", "Adesão"]}', 195, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre o manejo da SCA em gestantes, qual medicação deve ser EVITADA pelo risco de teratogenicidade ou danos fetais?", "options": {"a": "Aspirina (em doses baixas).", "b": "Estatinas e Inibidores da ECA / BRA.", "c": "Heparina de baixo peso.", "d": "Oxigênio.", "e": "Nitrato."}, "answer": "b", "rationale": "Estas drogas são contraindicadas na gravidez.", "option_rationales": {"a": "Incorreta. Usada com cautela.", "b": "Correta. Contraindicação formal.", "c": "Incorreta. É o anticoagulante de escolha na gestação.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Gestação", "Segurança", "SCA"]}', 196, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual o principal benefício do uso de estatinas em altas doses PREVIAMENTE ao cateterismo cardíaco em pacientes com SCA (estudo SECURE-PCI)?", "options": {"a": "Aumentar a pressão.", "b": "Reduzir o risco de lesão renal aguda induzida por contraste e diminuir a resposta inflamatória periprocedimento.", "c": "Cura a diabetes.", "d": "Tira a dor de cabeça.", "e": "Não traz benefício."}, "answer": "b", "rationale": "As estatinas têm efeito nefroprotetor e estabilizador endotelial agudo.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Uso preventivo das estatinas.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Estatinas", "Hemodinâmica", "SCA"]}', 197, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia shows uma artéria circunflexa que nasce do seio coronariano direito. Qual a conduta?", "options": {"a": "Cirurgia de urgência.", "b": "Geralmente é um achado benigno que não exige intervenção, a menos que haja aterosclerose obstrutiva associada.", "c": "Fazer bócio.", "d": "Tratar com antibiótico.", "e": "Suspender o cigarro apenas."}, "answer": "b", "rationale": "Muitas anomalias de origem são benignas (trajeto retro-aórtico da CX).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Conduta baseada no risco da anomalia.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Anatomia", "Anomalia", "SCA"]}', 193, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual o principal objetivo da reabilitação cardíaca após uma síndrome coronariana aguda?", "options": {"a": "Ganhar músculos para fisioculturismo.", "b": "Melhorar a capacidade funcional, controlar fatores de risco e reduzir o risco de novos eventos e mortalidade através de exercício supervisionado e mudança de estilo de vida.", "c": "Poder fumar novamente.", "d": "Aumentar a glicose.", "e": "Curar o câncer."}, "answer": "b", "rationale": "A reabilitação é parte integrante do tratamento global da DAC.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Finalidade da medicina física e preventiva.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Reabilitação", "Prevenção", "SCA"]}', 199, 'draft');
